  @Test
  void clinit_shouldInitializeAllEightEnumConstants() {
    // When: Calling values() which requires all enum constants to be initialized
    WorkflowNodeType[] values = WorkflowNodeType.values();

    // Then: All eight constants from lines 4-11 should be initialized
    assertThat(values).hasSize(8);
    assertThat(values).containsExactly(
        WorkflowNodeType.TIMER_FIRED_EVENT,
        WorkflowNodeType.SIGNAL_EVENT,
        WorkflowNodeType.FORM_REPLIED_EVENT,
        WorkflowNodeType.ACTIVITY_COMPLETED_EVENT,
        WorkflowNodeType.ACTIVITY_FAILED_EVENT,
        WorkflowNodeType.ACTIVITY_EXPIRED_EVENT,
        WorkflowNodeType.JOIN_ACTIVITY,
        WorkflowNodeType.ACTIVITY
    );
  }

  @Test
  void clinit_shouldAllowValueOfToFindInitializedConstants() {
    // When: Using valueOf to look up enum constants by name
    // This ensures the <clinit> method has properly registered all enum instances

    // Then: All constants should be findable
    assertThat(WorkflowNodeType.valueOf("TIMER_FIRED_EVENT"))
        .isEqualTo(WorkflowNodeType.TIMER_FIRED_EVENT);
    assertThat(WorkflowNodeType.valueOf("SIGNAL_EVENT"))
        .isEqualTo(WorkflowNodeType.SIGNAL_EVENT);
    assertThat(WorkflowNodeType.valueOf("FORM_REPLIED_EVENT"))
        .isEqualTo(WorkflowNodeType.FORM_REPLIED_EVENT);
    assertThat(WorkflowNodeType.valueOf("ACTIVITY_COMPLETED_EVENT"))
        .isEqualTo(WorkflowNodeType.ACTIVITY_COMPLETED_EVENT);
    assertThat(WorkflowNodeType.valueOf("ACTIVITY_FAILED_EVENT"))
        .isEqualTo(WorkflowNodeType.ACTIVITY_FAILED_EVENT);
    assertThat(WorkflowNodeType.valueOf("ACTIVITY_EXPIRED_EVENT"))
        .isEqualTo(WorkflowNodeType.ACTIVITY_EXPIRED_EVENT);
    assertThat(WorkflowNodeType.valueOf("JOIN_ACTIVITY"))
        .isEqualTo(WorkflowNodeType.JOIN_ACTIVITY);
    assertThat(WorkflowNodeType.valueOf("ACTIVITY"))
        .isEqualTo(WorkflowNodeType.ACTIVITY);
  }

  @Test
  void clinit_enumConstantsShouldBeUnique() {
    // When: Getting all enum constants
    WorkflowNodeType timerFired = WorkflowNodeType.TIMER_FIRED_EVENT;
    WorkflowNodeType signal = WorkflowNodeType.SIGNAL_EVENT;
    WorkflowNodeType formReplied = WorkflowNodeType.FORM_REPLIED_EVENT;
    WorkflowNodeType activityCompleted = WorkflowNodeType.ACTIVITY_COMPLETED_EVENT;
    WorkflowNodeType activityFailed = WorkflowNodeType.ACTIVITY_FAILED_EVENT;
    WorkflowNodeType activityExpired = WorkflowNodeType.ACTIVITY_EXPIRED_EVENT;
    WorkflowNodeType joinActivity = WorkflowNodeType.JOIN_ACTIVITY;
    WorkflowNodeType activity = WorkflowNodeType.ACTIVITY;

    // Then: Each constant should be a unique instance
    assertThat(timerFired).isNotSameAs(signal);
    assertThat(timerFired).isNotSameAs(formReplied);
    assertThat(timerFired).isNotSameAs(activityCompleted);
    assertThat(timerFired).isNotSameAs(activityFailed);
    assertThat(timerFired).isNotSameAs(activityExpired);
    assertThat(timerFired).isNotSameAs(joinActivity);
    assertThat(timerFired).isNotSameAs(activity);
  }

  @Test
  void clinit_enumConstantsShouldBeSingletons() {
    // When: Accessing the same enum constant multiple times
    WorkflowNodeType timerFired1 = WorkflowNodeType.TIMER_FIRED_EVENT;
    WorkflowNodeType timerFired2 = WorkflowNodeType.TIMER_FIRED_EVENT;

    // Then: The same singleton instance should be returned
    assertThat(timerFired1).isSameAs(timerFired2);
  }

  @Test
  void clinit_shouldInitializeEnumInDeclarationOrder() {
    // When: Checking the ordinal values of enum constants
    // The <clinit> method initializes them in the order they're declared (lines 4-11)

    // Then: Ordinals should match declaration order
    assertThat(WorkflowNodeType.TIMER_FIRED_EVENT.ordinal()).isEqualTo(0);
    assertThat(WorkflowNodeType.SIGNAL_EVENT.ordinal()).isEqualTo(1);
    assertThat(WorkflowNodeType.FORM_REPLIED_EVENT.ordinal()).isEqualTo(2);
    assertThat(WorkflowNodeType.ACTIVITY_COMPLETED_EVENT.ordinal()).isEqualTo(3);
    assertThat(WorkflowNodeType.ACTIVITY_FAILED_EVENT.ordinal()).isEqualTo(4);
    assertThat(WorkflowNodeType.ACTIVITY_EXPIRED_EVENT.ordinal()).isEqualTo(5);
    assertThat(WorkflowNodeType.JOIN_ACTIVITY.ordinal()).isEqualTo(6);
    assertThat(WorkflowNodeType.ACTIVITY.ordinal()).isEqualTo(7);
  }

  @Test
  void clinit_valuesShouldReturnArrayWithAllInitializedConstants() {
    // When: Calling values() to get all enum constants
    WorkflowNodeType[] values = WorkflowNodeType.values();

    // Then: The array should contain all constants initialized in <clinit>
    assertThat(values).isNotEmpty();
    assertThat(values[0]).isEqualTo(WorkflowNodeType.TIMER_FIRED_EVENT);
    assertThat(values[1]).isEqualTo(WorkflowNodeType.SIGNAL_EVENT);
    assertThat(values[2]).isEqualTo(WorkflowNodeType.FORM_REPLIED_EVENT);
    assertThat(values[3]).isEqualTo(WorkflowNodeType.ACTIVITY_COMPLETED_EVENT);
    assertThat(values[4]).isEqualTo(WorkflowNodeType.ACTIVITY_FAILED_EVENT);
    assertThat(values[5]).isEqualTo(WorkflowNodeType.ACTIVITY_EXPIRED_EVENT);
    assertThat(values[6]).isEqualTo(WorkflowNodeType.JOIN_ACTIVITY);
    assertThat(values[7]).isEqualTo(WorkflowNodeType.ACTIVITY);
  }

  @Test
  void clinit_enumConstantsShouldBeComparable() {
    // When: Comparing enum constants (which relies on proper initialization)
    WorkflowNodeType timerFired = WorkflowNodeType.TIMER_FIRED_EVENT;
    WorkflowNodeType signal = WorkflowNodeType.SIGNAL_EVENT;
    WorkflowNodeType activity = WorkflowNodeType.ACTIVITY;

    // Then: They should be comparable based on their ordinal values from <clinit>
    assertThat(timerFired.compareTo(signal)).isLessThan(0);
    assertThat(signal.compareTo(activity)).isLessThan(0);
    assertThat(activity.compareTo(timerFired)).isGreaterThan(0);
    assertThat(timerFired.compareTo(timerFired)).isEqualTo(0);
  }

  @Test
  void clinit_enumConstantsShouldBeUsableInSwitchStatements() {
    // When: Using enum constants in a switch statement (requires proper initialization)
    String result;
    switch (WorkflowNodeType.TIMER_FIRED_EVENT) {
      case TIMER_FIRED_EVENT:
        result = "timer_fired_event";
        break;
      case SIGNAL_EVENT:
        result = "signal_event";
        break;
      case FORM_REPLIED_EVENT:
        result = "form_replied_event";
        break;
      case ACTIVITY_COMPLETED_EVENT:
        result = "activity_completed_event";
        break;
      case ACTIVITY_FAILED_EVENT:
        result = "activity_failed_event";
        break;
      case ACTIVITY_EXPIRED_EVENT:
        result = "activity_expired_event";
        break;
      case JOIN_ACTIVITY:
        result = "join_activity";
        break;
      case ACTIVITY:
        result = "activity";
        break;
      default:
        result = "unknown";
        break;
    }

    // Then: The switch should work correctly
    assertThat(result).isEqualTo("timer_fired_event");
  }

  @Test
  void clinit_allEnumConstantsShouldBeUsableInSwitchStatements() {
    // When: Testing all enum constants in switch statements
    for (WorkflowNodeType nodeType : WorkflowNodeType.values()) {
      String result;
      switch (nodeType) {
        case TIMER_FIRED_EVENT:
          result = "timer_fired_event";
          break;
        case SIGNAL_EVENT:
          result = "signal_event";
          break;
        case FORM_REPLIED_EVENT:
          result = "form_replied_event";
          break;
        case ACTIVITY_COMPLETED_EVENT:
          result = "activity_completed_event";
          break;
        case ACTIVITY_FAILED_EVENT:
          result = "activity_failed_event";
          break;
        case ACTIVITY_EXPIRED_EVENT:
          result = "activity_expired_event";
          break;
        case JOIN_ACTIVITY:
          result = "join_activity";
          break;
        case ACTIVITY:
          result = "activity";
          break;
        default:
          result = "unknown";
          break;
      }

      // Then: Each constant should match correctly
      assertThat(result).isIn("timer_fired_event", "signal_event", "form_replied_event",
          "activity_completed_event", "activity_failed_event", "activity_expired_event",
          "join_activity", "activity");
    }
  }

